<template>
  <div class="page">
    <v-card flat class="hero pa-5 mb-4"><div class="d-flex flex-wrap align-center"><div><div class="text-overline">SALES &amp; COMMISSIONS</div><h1 class="text-h5 font-weight-bold">Commissions</h1><div class="grey--text">Track, approve and settle sales-agent commissions.</div></div><v-spacer></v-spacer><v-btn v-if="$can('commissions.create')" color="#165134" dark class="mr-2" @click="openCreate"><v-icon left>mdi-plus</v-icon>Add Commission</v-btn><v-btn icon :loading="loading" @click="load"><v-icon>mdi-refresh</v-icon></v-btn></div></v-card>
    <v-card flat outlined class="mb-4"><v-card-text><v-row dense><v-col cols="12" md="4"><v-select v-model="filters.status" :items="statuses" outlined dense clearable label="Status" @change="load"></v-select></v-col><v-col cols="12" md="4"><v-select v-model="filters.agent_id" :items="agents" item-text="name" item-value="id" outlined dense clearable label="Sales Agent" @change="load"></v-select></v-col><v-col cols="12" md="4" class="d-flex align-center"><v-chip outlined>{{ items.length }} shown</v-chip></v-col></v-row></v-card-text></v-card>
    <v-card flat outlined><v-data-table :headers="headers" :items="items" :loading="loading" :options.sync="options" :server-items-length="total"><template v-slot:item.commission_amount="{ item }"><strong>{{ money(item.commission_amount) }}</strong></template><template v-slot:item.percentage="{ item }">{{ item.percentage }}%</template><template v-slot:item.status="{ item }"><v-chip x-small :color="statusColor(item.status)" dark>{{ item.status }}</v-chip></template><template v-slot:item.actions="{ item }"><v-menu v-if="$can('commissions.edit')" offset-y><template v-slot:activator="{ on, attrs }"><v-btn icon small v-bind="attrs" v-on="on"><v-icon small>mdi-dots-vertical</v-icon></v-btn></template><v-list dense><v-list-item v-for="status in nextStatuses(item.status)" :key="status" @click="openStatusChange(item, status)"><v-list-item-title>Mark {{ status }}</v-list-item-title></v-list-item><v-divider v-if="item.status==='paid'"></v-divider><v-list-item v-if="item.status==='paid'" @click="openReverse(item)"><v-list-item-icon><v-icon small color="error">mdi-undo</v-icon></v-list-item-icon><v-list-item-title class="error--text">Reverse payment</v-list-item-title></v-list-item></v-list></v-menu></template><template v-slot:no-data><div class="pa-8 grey--text">No commissions found.</div></template></v-data-table></v-card>
    <v-dialog v-model="createDialog" max-width="720" persistent>
      <v-card>
        <v-card-title>Add Commission<v-spacer/><v-btn icon :disabled="saving" @click="createDialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title>
        <v-card-text>
          <v-alert type="info" text dense>Choose a booking with an assigned sales agent. Commission is calculated from the booking final price.</v-alert>
          <v-autocomplete v-model="form.booking_id" :items="bookings" :item-text="bookingLabel" item-value="id" outlined dense label="Sale / Booking *" no-data-text="No eligible sales/bookings found" :loading="loadingBookings" @change="bookingChanged"/>
          <v-text-field :value="selectedBooking && selectedBooking.property ? ((selectedBooking.property.property_number||'Property')+(selectedBooking.property.project?' — '+selectedBooking.property.project.name:'')) : ''" outlined dense readonly label="Property"/><v-text-field :value="selectedBooking ? money(selectedBooking.final_price) : ''" outlined dense readonly label="Sale / Final Price" prefix="PKR"/>
          <v-autocomplete v-model="form.agent_id" :items="agents" item-text="name" item-value="id" outlined dense label="Sales Agent *" readonly/>
          <v-text-field v-model="form.percentage" type="number" min="0" max="100" step="0.01" outlined dense label="Commission Rate (%) *" suffix="%"/>
          <v-text-field :value="money(calculatedCommission)" outlined dense readonly label="Calculated Commission" prefix="PKR"/>
          <v-textarea v-model="form.notes" outlined dense rows="3" label="Notes"/>
        </v-card-text>
        <v-card-actions><v-spacer/><v-btn text :disabled="saving" @click="createDialog=false">Cancel</v-btn><v-btn color="#165134" dark :loading="saving" @click="createCommission">Create Commission</v-btn></v-card-actions>
      </v-card>
    </v-dialog>
    <v-dialog v-model="reverseDialog" max-width="520"><v-card><v-card-title>Reverse commission payment</v-card-title><v-card-text><v-alert type="warning" text dense>This returns the paid commission to approved status and records an audit entry.</v-alert><v-textarea v-model="reverseReason" label="Reason for reversal" outlined rows="3" :error-messages="reverseError"></v-textarea></v-card-text><v-card-actions><v-spacer></v-spacer><v-btn text @click="reverseDialog=false">Cancel</v-btn><v-btn color="error" :loading="reversing" @click="reversePayment">Reverse payment</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="statusDialog" max-width="480" persistent><v-card><v-card-title>Confirm commission status</v-card-title><v-card-text><v-alert type="warning" text dense>Change this commission from <strong>{{ statusItem && statusItem.status }}</strong> to <strong>{{ statusTarget }}</strong>? This financial status change is recorded in the audit trail.</v-alert></v-card-text><v-card-actions><v-spacer/><v-btn text :disabled="statusSaving" @click="statusDialog=false">Cancel</v-btn><v-btn color="#165134" dark :loading="statusSaving" @click="confirmStatusChange">Confirm</v-btn></v-card-actions></v-card></v-dialog>
  </div>
</template>
<script>
import api from '../../../services/api'
export default {name:'Commissions',data:()=>({loading:false,createDialog:false,saving:false,loadingBookings:false,bookings:[],form:{booking_id:null,agent_id:null,percentage:null,notes:''},reverseDialog:false,reversing:false,reverseItem:null,reverseReason:'',reverseError:[],statusDialog:false,statusSaving:false,statusItem:null,statusTarget:null,items:[],total:0,agents:[],options:{page:1,itemsPerPage:15},filters:{status:null,agent_id:null},statuses:['pending','approved','paid','cancelled'],headers:[{text:'Agent',value:'agent.name'},{text:'Customer',value:'booking.customer.name'},{text:'Booking',value:'booking.booking_number'},{text:'Base Amount',value:'base_amount',align:'right'},{text:'Rate',value:'percentage',align:'right'},{text:'Commission',value:'commission_amount',align:'right'},{text:'Status',value:'status'},{text:'',value:'actions',sortable:false}]}),watch:{options:{deep:true,handler(){this.load()}}},computed:{selectedBooking(){return this.bookings.find(b=>Number(b.id)===Number(this.form.booking_id))||null},calculatedCommission(){return this.selectedBooking?Number(this.selectedBooking.final_price||0)*Number(this.form.percentage||0)/100:0}},mounted(){this.load();this.loadAgents()},methods:{openCreate(){this.form={booking_id:null,agent_id:null,percentage:null,notes:''};this.createDialog=true;this.loadBookings()},async loadBookings(){this.loadingBookings=true;try{const response=await api.get('/bookings',{params:{per_page:100}});this.bookings=(response.data.data||[]).filter(b=>b.status!=='cancelled')}catch(error){this.bookings=[];this.$root.$emit('show-error',(error.response&&error.response.data&&error.response.data.message)||'Unable to load eligible bookings.')}finally{this.loadingBookings=false}},bookingLabel(b){const property=b.property?(b.property.property_number||'Property'):'Property';const project=b.property&&b.property.project?b.property.project.name:'';return (b.booking_number||('Booking #'+b.id))+' — '+property+(project?' / '+project:'')+' — '+(b.customer?b.customer.name:'Customer')+' — PKR '+this.money(b.final_price)},bookingChanged(){const b=this.selectedBooking;this.form.agent_id=b?b.sales_agent_id:null},async createCommission(){if(!this.form.booking_id||!this.form.agent_id||this.form.percentage===null||this.form.percentage===''){this.$root.$emit('show-error','Booking, sales agent and commission rate are required.');return}const rate=Number(this.form.percentage);if(rate<0||rate>100){this.$root.$emit('show-error','Commission rate must be between 0 and 100.');return}this.saving=true;try{const response=await api.post('/commissions',this.form);this.createDialog=false;this.$root.$emit('show-success',response.data.message||'Commission created successfully.');await this.load()}catch(error){this.$root.$emit('show-error',(error.response&&error.response.data&&error.response.data.message)||'Unable to create commission.')}finally{this.saving=false}},async load(){this.loading=true;try{const response=await api.get('/commissions',{params:Object.assign({},this.filters,{page:this.options.page,per_page:this.options.itemsPerPage})});this.items=response.data.data||[];this.total=response.data.total||0}catch(error){this.$root.$emit('show-error',(error.response&&error.response.data&&error.response.data.message)||'Unable to load commissions.')}finally{this.loading=false}},async loadAgents(){try{const response=await api.get('/sales-agents');this.agents=response.data.data||[]}catch(error){this.agents=[]}},money(value){return new Intl.NumberFormat('en-PK',{maximumFractionDigits:0}).format(Number(value||0))},statusColor(status){return{pending:'orange',approved:'blue',paid:'success',cancelled:'grey'}[status]||'grey'},nextStatuses(status){if(status==='pending')return ['approved','cancelled'];if(status==='approved')return ['paid','cancelled'];return []},openStatusChange(item,status){this.statusItem=item;this.statusTarget=status;this.statusDialog=true},async confirmStatusChange(){if(!this.statusItem||!this.statusTarget)return;this.statusSaving=true;try{await api.put('/commissions/'+this.statusItem.id,{status:this.statusTarget});this.statusDialog=false;this.$root.$emit('show-success','Commission status updated successfully.');await this.load()}catch(error){this.$root.$emit('show-error',(error.response&&error.response.data&&error.response.data.message)||'Unable to update commission.')}finally{this.statusSaving=false}},openReverse(item){this.reverseItem=item;this.reverseReason='';this.reverseError=[];this.reverseDialog=true},async reversePayment(){this.reverseError=[];if(!this.reverseReason.trim()){this.reverseError=['Reason is required.'];return}this.reversing=true;try{await api.post('/commissions/'+this.reverseItem.id+'/reverse',{reason:this.reverseReason.trim()});this.reverseDialog=false;this.$root.$emit('show-success','Commission payment reversed successfully.');await this.load()}catch(error){this.reverseError=[(error.response&&error.response.data&&error.response.data.message)||'Unable to reverse commission payment.']}finally{this.reversing=false}}}}
</script><style scoped>.page{width:100%}.hero{border-left:4px solid #165134}.page ::v-deep .v-data-table__wrapper{overflow-x:auto}</style>
